<?php require_once __DIR__.'/../../config/database.php';require_once __DIR__.'/../../helpers/auth.php';$id=(int)($_GET['id']??0);$page_title=$id?'Edit Produk':'Tambah Produk';$err='';$p=['category_id'=>'','sku'=>'','name'=>'','price'=>'','minimum_stock'=>5];if($id){$q=$pdo->prepare('SELECT * FROM products WHERE id=?');$q->execute([$id]);$p=$q->fetch();if(!$p)die('Produk tidak ditemukan.');}if($_SERVER['REQUEST_METHOD']==='POST'){$cat=(int)$_POST['category_id'];$sku=trim($_POST['sku']);$name=trim($_POST['name']);$price=(float)$_POST['price'];$min=(int)$_POST['minimum_stock'];if(!$cat||$sku===''||$name===''||$price<0||$min<0)$err='Data belum valid.';else try{if($id){$q=$pdo->prepare('UPDATE products SET category_id=?,sku=?,name=?,price=?,minimum_stock=? WHERE id=?');$q->execute([$cat,$sku,$name,$price,$min,$id]);}else{$q=$pdo->prepare('INSERT INTO products(category_id,sku,name,price,stock,minimum_stock) VALUES(?,?,?,?,0,?)');$q->execute([$cat,$sku,$name,$price,$min]);}header('Location:index.php');exit;}catch(PDOException $e){$err='SKU sudah digunakan.';}}$cats=$pdo->query('SELECT * FROM categories ORDER BY name')->fetchAll();require __DIR__.'/../../views/header.php';?><div class="card"><?php if($err):?><div class="alert"><?=e($err)?></div><?php endif;?><form method="post" class="grid"><div><label>SKU</label><input name="sku" value="<?=e($p['sku'])?>" required></div><div><label>Nama Produk</label><input name="name" value="<?=e($p['name'])?>" required></div><div><label>Kategori</label><select name="category_id" required><option value="">Pilih</option><?php foreach($cats as $c):?><option value="<?=$c['id']?>" <?=$p['category_id']==$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach;?></select></div><div><label>Harga</label><input type="number" min="0" name="price" value="<?=e($p['price'])?>" required></div><div><label>Minimum Stok</label><input type="number" min="0" name="minimum_stock" value="<?=e($p['minimum_stock'])?>" required></div><div><button class="btn">Simpan</button> <a class="btn" href="index.php">Batal</a></div></form></div><?php require __DIR__.'/../../views/footer.php';
